function lang(){return texts[w.LOCALE]?w.LOCALE:'fr';}
function t(k){return texts[lang()][keys.indexOf(k)]||(w.VerdictCarteAtelier?w.VerdictCarteAtelier.text(k):k);}
function activeDish(p){return !p.cpArchived;}
function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
function money(v){return typeof v==='number'&&isFinite(v)?v.toLocaleString(lang(),{style:'currency',currency:'EUR'}):'—';}
/* C208 (V57) : un total de la carte s'écrit à l'euro, comme dans le récit et l'Audit ; les centimes restent au plat. */
function money0(v){return typeof v==='number'&&isFinite(v)?v.toLocaleString(lang(),{style:'currency',currency:'EUR',minimumFractionDigits:0,maximumFractionDigits:0}):'—';}
function number(v){return typeof v==='number'&&isFinite(v)?v.toLocaleString(lang()):'—';}
function data(){return w.DB||{plats:[],ing:[],reg:{}};}
function ref(){return w.point5ReferenceState();}
function guided(){return !!(d.body&&d.body.classList.contains('demo-tour-active'));}
function button(label,page,extra){return '<button type="button" class="cp-button" data-cp-page="'+page+'"'+(extra||'')+'>'+esc(label)+'</button>';}
/* C218 (W37, demande de L3) : période écrite en français (« janvier 2025 → décembre 2025 »), comme la carte « Mois analysé » de 029. */
function perTxt(x){try{return typeof w.point5PeriodeTxt==='function'?w.point5PeriodeTxt(x):x;}catch(e){return x;}}
function context(){var r=ref();return '<div class="cp-context">'+esc(r.demo?t('demo'):(r.ready?((w.DB&&w.DB.carteRef&&w.DB.carteRef.moyenne)?'moyenne '+perTxt(w.DB.carteRef.moyenne.debut)+' → '+perTxt(w.DB.carteRef.moyenne.fin):perTxt(r.period))+' · '+w.point5SourceLabel(r.source):t('missingPeriod')))+(r.estimated?' · '+esc(t('estimate')):'')+'</div>';}
function title(k){return '<div class="cp-pagehead"><button type="button" class="cp-back" data-cp-back>'+esc(t('back'))+'</button><h2 tabindex="-1" data-cp-title>'+esc(t(k))+'</h2></div>';}
function metric(label,value){return '<div class="cp-metric"><span>'+esc(label)+'</span><strong>'+esc(value)+'</strong></div>';}
function dishById(id){return (data().plats||[]).find(function(p){return String(p.id)===String(id);});}
function categories(){var a=[];(data().plats||[]).filter(activeDish).forEach(function(p){var k=p.cat||'Autre';if(a.indexOf(k)<0)a.push(k);});var rank=window.VerdictCourseRank||(window.VerdictCourseRank=(function(){var R=[[/petit.?dejeuner|breakfast|brunch/,0],[/supplement|extra|option|topping/,11],[/alcool|vin|biere|cocktail|spiritueux|champagne/,10],[/boisson|^bar$|cafe|salon de the|the |soft|jus|smoothie/,9],[/dessert|patisserie|viennoiserie|glace|gourmandise|sucre/,8],[/fromage/,7],[/accompagnement|friture|frite|side|garniture/,6],[/menu|formule/,5],[/entree|starter|a partager|tapas|aperitif|amuse/,1],[/salade/,2],[/plat du jour|plats du jour|suggestion/,3],[/plat|a la carte|bowl|burger|pizza|pate|tacos|taco|sandwich|wrap|assiette|fruits de mer|poisson|viande|grill|room service|snack|pain|poke|kebab|sushi|wok|tartine|croque|quiche|galette|street/,4]];function norm(k){return String(k||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();}return function(k){var n=norm(k);for(var i=0;i<R.length;i++)if(R[i][0].test(n))return R[i][1];return 12;};})());return a.sort(function(a,b){return rank(a)-rank(b)||a.localeCompare(b,lang());});}
function volumeKnown(p){return p.vol!==null&&p.vol!==undefined&&p.vol!==''&&Number.isFinite(Number(p.vol))&&Number(p.vol)>=0;}
var goalLabels={fr:'de l’objectif de contribution',en:'of the contribution target',es:'del objetivo de contribución',it:'dell’obiettivo di contributo',de:'des Beitragsziels',nl:'van het bijdragedoel',pt:'da meta de contribuição'};
function tone(ratio){if(typeof ratio!=='number'||!isFinite(ratio))return 'neutral';return window.VerdictExact.zoneRatio(ratio);}
function dishRatio(k){return k&&ref().ready&&k.complete&&Number.isFinite(k.contribPct)&&k.objPond>0?k.contribPct/k.objPond:null;}
function goalBadge(ratio,m,o){if(ratio==null)return '';if(typeof m==='number'&&isFinite(m)&&typeof o==='number'&&isFinite(o))return '<span class="cp-goal" data-mag-goal>'+esc(mt('marge',{m:pct(m),o:pct(o)}))+'</span>';return '<span class="cp-goal">'+esc((ratio*100).toLocaleString(lang(),{maximumFractionDigits:1}))+' % '+esc(goalLabels[lang()])+'</span>';}
function menuMarge(){if(!ref().ready)return {};var a=0,tg=0,ht=0,VA=volActifs();(data().plats||[]).forEach(function(p,i){var k=w.platCalc(p),v=VA?VA.vol(i):Number(p.vol);if(k.complete&&v>0&&k.objPond>0&&k.htPond>0){a+=k.contribPond*v;tg+=k.htPond*k.objPond/100*v;ht+=k.htPond*v;}});return ht>0?{m:a/ht*100,o:tg/ht*100}:{};}
/* C251 (L7, avec C254 de L3) : un plat retiré ne compte plus dans l'en-tête de « Ma carte » ; 70 % de ses ventes vont aux plats actifs complets de sa catégorie, comme carteStats(). Sans C254, volume de la caisse. */
function volActifs(){try{return typeof w.carteVolumesActifs==='function'?w.carteVolumesActifs():null;}catch(e){return null;}}
function menuRatio(){if(!ref().ready)return null;var actual=0,target=0,VA=volActifs();(data().plats||[]).forEach(function(p,i){var k=w.platCalc(p),v=VA?VA.vol(i):Number(p.vol);if(k.complete&&v>0&&k.objPond>0){actual+=k.contribPond*v;target+=k.htPond*k.objPond/100*v;}});return target>0?actual/target:null;}
function row(p,mode){var k=w.platCalc(p),r=ref(),valid=r.ready&&k.complete&&volumeKnown(p),vol=valid?Number(p.vol)||0:null;return '<button type="button" class="cp-dish" data-cp-tone="'+tone(dishRatio(k))+'" data-cp-dish="'+esc(p.id)+'"><span class="cp-dish-main"><strong>'+esc(p.nom)+'</strong><span>'+esc(mode==='sales'?(p.cat||'')+(p.cpArchived?' · '+t('archived'):''):(k.complete?t('unitContribution')+' '+money(k.contribPond):t('incomplete')))+'</span>'+goalBadge(dishRatio(k),k&&k.contribPct,k&&k.objPond)+'</span><span class="cp-dish-values"><strong>'+esc(mode==='sales'?money(valid?k.contribPond*vol:null):money(Number(p.ttc)))+'</strong><span>'+esc(mode==='sales'?(vol==null?t('unknown'):({fr:'reste après produits',en:'left after food cost',es:'queda tras el producto',it:'resta dopo i prodotti',de:'Rest nach Wareneinsatz',nl:'over na inkoop',pt:'resta após produtos'}[lang()]||'reste après produits')+' · '+number(vol)+' '+t('sold').toLowerCase()):t('price'))+'</span></span></button>';}
function menu(){var host=d.getElementById('c-menu');host.innerHTML='<div class="cp-menuhead"><div><p class="cp-eyebrow">'+esc(data().nom||data().etab||t('menu'))+'</p><h2 data-cp-title tabindex="-1">'+esc(t('menu'))+'</h2>'+goalBadge(menuRatio(),menuMarge().m,menuMarge().o)+'</div><button class="cp-button cp-primary" type="button" data-cp-add>'+esc(t('add'))+'</button></div>'+'<div class="cp-actions">'+button(t('rotate'),'rotation')+'</div>'+context()+'<label class="cp-search"><span class="cp-sr">'+esc(t('search'))+'</span><input type="search" id="cp-search" placeholder="'+esc(t('search'))+'" value="'+esc(S.query)+'"></label><div class="cp-categories" role="group" aria-label="'+esc(t('categories'))+'">'+[''].concat(categories()).map(function(c){return '<button type="button" data-cp-category="'+esc(c)+'" aria-pressed="'+(S.category===c)+'">'+esc(c||t('all'))+'</button>';}).join('')+'</div><div id="cp-menu-list"></div>';menuList();}
function menuList(){var list=d.getElementById('cp-menu-list');if(!list)return;var a=(data().plats||[]).filter(function(p){return activeDish(p)&&(!S.category||p.cat===S.category)&&(!S.query||(p.nom+' '+p.cat).toLocaleLowerCase().includes(S.query.toLocaleLowerCase()));});list.innerHTML=categories().map(function(c){var rows=a.filter(function(p){return (p.cat||'Autre')===c;});return rows.length?'<section class="cp-category"><h3>'+esc(c)+' <span>'+rows.length+'</span></h3><div class="cp-list">'+rows.map(function(p){return row(p,'menu');}).join('')+'</div></section>':'';}).join('')||'<div class="cp-empty">'+esc(data().plats.some(activeDish)?t('noMatch'):t('empty'))+'</div>';}
function rememberGroups(){d.querySelectorAll('[data-cp-group]').forEach(function(el){S.expanded[el.dataset.cpGroup]=el.hasAttribute('open');});}
var expandLabels={fr:['Tout déplier','Tout replier'],en:['Expand all','Collapse all'],es:['Expandir todo','Contraer todo'],it:['Espandi tutto','Comprimi tutto'],de:['Alle aufklappen','Alle zuklappen'],nl:['Alles uitklappen','Alles inklappen'],pt:['Expandir tudo','Recolher tudo']};
function decisionsList(P){return (P.items.length?'<div class="cp-actions cp-expand-actions"><button type="button" class="cp-button" data-cp-expand="true">'+esc(expandLabels[lang()][0])+'</button><button type="button" class="cp-button" data-cp-expand="false">'+esc(expandLabels[lang()][1])+'</button></div>':'')+ ['o','r','p','g','s','x'].map(function(code){var rows=P.items.filter(function(x){return x.z.k===code;});return rows.length?'<details class="cp-card" data-cp-group="'+code+'"'+(S.expanded[code]?' open':'')+'><summary>'+esc(rows[0].z.lb)+' · '+rows.length+'</summary><div class="cp-list" style="margin-top:16px">'+rows.map(function(x){return row(x.p,'sales');}).join('')+'</div></details>':'';}).join('');}
function sales(st){var r=ref(),rows=(data().plats||[]).slice().sort(function(a,b){var x=w.platCalc(a),y=w.platCalc(b);return (y.complete?y.contribPond*(Number(b.vol)||0):0)-(x.complete?x.contribPond*(Number(a.vol)||0):0);});return '<h2 tabindex="-1" data-cp-title>'+esc(t('sales'))+'</h2>'+context()+button(t('imports'),'imports')+'<div class="cp-metrics">'+metric(t('sold'),r.ready?number(st.vol):'—')+metric(t('coverage'),r.ready?number(st.volFiable)+' / '+number(st.vol):'—')+'</div><p class="cp-note">'+esc(t('salesNote'))+' '+esc(t('beforeFixed'))+'</p><div class="cp-list">'+rows.map(function(p){return row(p,'sales');}).join('')+'</div>';}
function dish(){var p=dishById(S.dish),host=d.getElementById('c-dish');if(!p){host.setAttribute('data-cp-tone',tone(dishRatio(k)));host.innerHTML=title('dish')+'<p>'+esc(t('empty'))+'</p>';return;}var k=w.platCalc(p),r=ref(),valid=r.ready&&k.complete&&volumeKnown(p),v=Number(p.vol)||0;
host.setAttribute('data-cp-tone',tone(dishRatio(k)));host.innerHTML=title('dish')+'<div class="cp-detail-title"><p class="cp-eyebrow">'+esc(p.cat||'')+'</p><h3>'+esc(p.nom)+'</h3>'+goalBadge(dishRatio(k),k&&k.contribPct,k&&k.objPond)+'<strong>'+esc(money(Number(p.ttc)))+' <small>'+esc(t('price'))+'</small></strong></div>'+context()+(w.VerdictCarteAtelier?w.VerdictCarteAtelier.quoteHTML(p):'')+(p.cpArchived?'':'<p class="cp-note">'+esc(w.platZone(p,w.carteStats()).act)+'</p>'+advisor(p))+'<div class="cp-metrics">'+metric(t('sold'),r.ready&&volumeKnown(p)?number(v):'—')+metric(t('contribution'),valid?money(k.contribPond*v):'—')+'</div><section class="cp-card"><h3>'+esc(t('unitContribution'))+'</h3><div class="cp-breakdown">'+metric(t('cost'),k.recetteComplete?money(k.cout):t('incomplete'))+metric(t('unitContribution'),k.complete?money(k.contribPond):'—')+metric(t('labor'),k.labor&&k.labor.ready?money(k.labor.cost):t('unknown'))+metric(t('direct'),k.directComplete?money(k.directContribPond):'—')+'</div><p class="cp-note">'+esc(t('beforeFixed'))+'</p></section>'+(p.cpArchived?'<button class="cp-button cp-primary" data-qa-reuse="'+esc(p.id)+'">'+esc(t('reuse'))+'</button>':'<div class="cp-actions"><button class="cp-button cp-primary" data-cp-edit="'+esc(p.id)+'">'+esc(t('edit'))+'</button>'+button(t('preview'),'sim')+'</div>')+'<details class="cp-card"><summary>'+esc(t('readRecipe'))+'</summary><div class="cp-recipe">'+(p.rec||[]).map(function(r){var ing=(data().ing||[]).find(function(i){return i.nom===r[0];});return '<p><span>'+esc(r[0])+'</span><b>'+esc(number(Number(r[1])))+' '+esc(ing&&ing.type==='UNITE'?'u':ing&&ing.type==='L'?'ml':'g')+'</b></p>';}).join('')+(p.preps||[]).map(function(r){var prep=(data().preparations||[]).find(function(x){return x.id===r[0];});return '<p><span>'+esc(prep?prep.nom:t('preparations'))+'</span><b>'+esc(number(Number(r[1])))+' '+esc(prep&&prep.unit||'')+'</b></p>';}).join('')+'</div>'+(p.cpArchived?'':'<button class="cp-button" data-cp-edit="'+esc(p.id)+'">'+esc(t('editRecipe'))+'</button>')+'</details>';
}
function simulator(){var rows=(data().plats||[]).filter(activeDish),p=rows.find(function(x){return x.id===S.dish;})||rows[0];if(p)S.dish=p.id;var host=d.getElementById('c-sim'),k=p&&w.platCalc(p);function input(id,label,value,min,step){return '<label class="f"><span>'+esc(label)+'</span><input id="'+id+'" type="number" min="'+min+'" step="'+step+'" value="'+esc(value)+'"></label>';}
 host.innerHTML=title('simulation')+'<label class="f"><span>'+esc(t('selectDish'))+'</span><select id="cp-sim-dish">'+rows.map(function(x){return '<option value="'+esc(x.id)+'"'+(p&&x.id===p.id?' selected':'')+'>'+esc(x.nom)+'</option>';}).join('')+'</select></label>'+(p?'<div class="cp-card"><div class="g2">'+input('cp-sim-price',t('newPrice'),p.ttc,.01,.01)+(p.pf?input('cp-sim-platform',at('platform'),p.pfttc,.01,.01):'')+input('cp-sim-cost',at('adjustedCost'),k.recetteComplete?Number(k.cout.toFixed(4)):'',0,.01)+input('cp-sim-volume',t('newVolume'),volumeKnown(p)?p.vol:'',0,1)+'</div><div id="cp-sim-result" aria-live="polite"></div></div>':'<p>'+esc(t('empty'))+'</p>')+'<p class="cp-note">'+esc(t('simulationNote'))+'</p><p class="cp-note">'+esc(at('guard'))+'</p>'+button(t('resistance'),'cstress');simulate();}
function scenario(p,price,volume,foodCost,platformPrice){if(!p||!Number.isFinite(price)||price<=0||!Number.isInteger(volume)||volume<0)return null;var next=Object.assign({},p,{ttc:price,vol:volume});if(platformPrice!==undefined){if(!Number.isFinite(platformPrice)||platformPrice<=0)return null;next.pfttc=platformPrice;}var base=w.platCalc(p),test=w.platCalc(next);if(!base.complete||!test.complete)return null;if(foodCost===undefined)foodCost=test.cout;if(!Number.isFinite(foodCost)||foodCost<0)return null;var unit=test.contribPond+test.cout-foodCost,ratio=test.htPond>0&&test.objPond>0?unit/test.htPond*100/test.objPond:null;return {unit:unit,current:volumeKnown(p)?base.contribPond*Number(p.vol):null,value:unit*volume,ratio:ratio,marge:test.htPond>0?unit/test.htPond*100:null,obj:test.objPond};}
function simulate(){var p=dishById(S.dish),price=d.getElementById('cp-sim-price'),volume=d.getElementById('cp-sim-volume'),cost=d.getElementById('cp-sim-cost'),platform=d.getElementById('cp-sim-platform'),host=d.getElementById('cp-sim-result');if(!host||!price||!volume||!cost)return;var result=price.value.trim()&&volume.value.trim()&&cost.value.trim()&&(!platform||platform.value.trim())?scenario(p,Number(price.value),Number(volume.value),Number(cost.value),platform?Number(platform.value):undefined):null;
 host.innerHTML=result?'<section class="cp-advice cp-card cp-revealed" data-cp-tone="'+tone(result.ratio)+'"><h3>'+esc(at('impact'))+'</h3>'+goalBadge(result.ratio,result.marge,result.obj)+'<div class="cp-metrics">'+metric(t('unitContribution'),money(result.unit))+metric(t('scenario'),money(result.value))+'</div>'+(ref().ready&&result.current!=null?'<p class="cp-note">'+esc(t('current'))+' '+esc(money(result.current))+' · '+esc(t('difference'))+' '+esc(money(result.value-result.current))+'</p>':'')+'<p class="cp-note">'+esc(t('beforeFixed'))+'</p></section>':'<p class="cp-note">'+esc(t('incomplete'))+'</p>';}
