function at(k){return adviceText[lang()][adviceKeys.indexOf(k)]||k;}
function pct(v){return number(Math.round(v*10)/10)+'\u00a0%';}
function plan(p){
 var k=p&&w.platCalc(p);if(!k||!k.complete||!(k.objPond>0&&k.objPond<100)||!Number.isFinite(k.contribPct))return null;
 var target=k.objPond/100,gap=Math.max(0,k.htPond*target-k.contribPond),ratio=k.contribPct/k.objPond;
 var result={k:k,ratio:ratio,gap:gap,costCap:k.cout-gap,price:null,pfPrice:null,gain:null};
 if(ratio>=1)return result;
 // Solve against the same business engine. Platform commission and VAT remain active.
 function scaled(f){return Object.assign({},p,{ttc:Number(p.ttc)*f,pfttc:p.pf?Number(p.pfttc)*f:p.pfttc});}
 function passes(f){var n=w.platCalc(scaled(f));return n.complete&&n.contribPct>=n.objPond;}
 // C88 : hausse réaliste, au plus +8 % et jamais au-dessus du plat le plus cher de sa catégorie ; le gain compte 3 % de ventes en moins.
 var top=0;(data().plats||[]).forEach(function(x){if(activeDish(x)&&(x.cat||'Autre')===(p.cat||'Autre'))top=Math.max(top,Number(x.ttc)||0);});
 var hi=Number(p.ttc)<top?Math.min(1.08,top/Number(p.ttc)):1.08,capped=!passes(hi);
 if(hi>1.0005){if(!capped){var lo=1;for(var i=0;i<55;i++){var mid=(lo+hi)/2;if(passes(mid))hi=mid;else lo=mid;}}
  var cut=function(v){return capped?Math.floor((v+1e-9)*10)/10:Math.ceil((v-1e-9)*10)/10;},candidate=scaled(hi);candidate.ttc=cut(candidate.ttc);if(p.pf)candidate.pfttc=cut(candidate.pfttc);
  var next=w.platCalc(candidate);if(next.complete&&candidate.ttc>Number(p.ttc)){result.price=candidate.ttc;result.pfPrice=p.pf?candidate.pfttc:null;result.capped=capped;result.gain=next.contribPond*.97-k.contribPond;result.next=next;}
 }
 return result;
}
function advisor(p){var a=plan(p);if(!a)return '<section class="cp-card cp-advice"><h3>'+esc(mt('action'))+'</h3><p class="cp-note">'+esc(at('missing'))+'</p><button class="cp-button" data-cp-edit="'+esc(p.id)+'">'+esc(t('edit'))+'</button></section>';
 var k=a.k,ready=ref().ready&&volumeKnown(p),under=a.ratio<1,percent=pct(a.ratio*100),costCap=Math.floor((a.costCap+1e-9)*100)/100;
 return '<section class="cp-card cp-advice" data-cp-tone="'+tone(a.ratio)+'"><p class="cp-eyebrow">VERDICT · '+esc(under?at('trial'):at('reached'))+'</p><h3>'+esc(under?mt('action'):at('reached'))+'</h3><div class="cp-target" data-mag-target><strong>'+esc(pct(k.contribPct))+'</strong><span>'+esc(mt('objectif'))+' <b>'+esc(pct(k.objPond))+'</b></span></div><div class="cp-target-track"><span style="--cp-progress:'+Math.max(0,Math.min(100,a.ratio*100))+'%"></span></div>'+(under?magLigne(p,a):'<p class="cp-note">'+esc(mt('marge',{m:pct(k.contribPct),o:pct(k.objPond)}))+'</p>')+(under?
 '<div class="cp-levers">'+(costCap>=0?'<article class="cp-lever"><span class="cp-step">01</span><h4>'+esc(at('costTarget'))+'</h4><strong class="cp-lever-value">'+esc(money(costCap))+'</strong><p>'+esc(at('saveUnit'))+' <b>'+esc(money(k.cout-costCap))+'</b></p><button class="cp-button cp-primary" data-cp-plan="cost">'+esc(at('testCost'))+'</button></article>':'')+
 (a.price!=null?'<article class="cp-lever"><span class="cp-step">02</span><h4>'+esc(at('priceTarget'))+'</h4><strong class="cp-lever-value">'+esc(money(a.price))+'</strong><p>'+esc(money(Number(p.ttc)))+' · +'+esc(pct((a.price/Number(p.ttc)-1)*100))+'</p>'+(p.pf?'<p>'+esc(at('platform'))+' <b>'+esc(money(a.pfPrice))+'</b></p>':'')+(ready?'<p>'+esc(at('gainPeriod'))+' <b>+'+esc(money(a.gain*Number(p.vol)))+'</b> · '+esc(at('sameVolume'))+' ('+esc(number(Number(p.vol)))+')</p>':'')+'<button class="cp-button" data-cp-plan="price">'+esc(at('testPrice'))+'</button></article>':'')+'</div>'+
 (a.price==null&&costCap<0?'<p class="cp-note">'+esc(at('impossible'))+'</p>':'')+
 '<p class="cp-note">'+esc(at('assumptions'))+'</p>'+(a.price&&a.capped?'<p class="cp-caution">'+esc(at('priceLimit'))+'</p>':'')+'<details class="cp-method"><summary>'+esc(t('cost'))+' · '+esc(t('recipe'))+'</summary><p class="cp-note">'+esc(at('materialLimit'))+'</p></details>':'')+'<p class="cp-note">'+esc(at('volumeAlert'))+'</p></section>';
}
