function mt(k,p){var D=MAG[lang()]||MAG.fr,v=D[k]!=null?D[k]:(MAG.fr[k]!=null?MAG.fr[k]:k);return p?String(v).replace(/\{(\w+)\}/g,function(_,x){return p[x]!=null?p[x]:'';}):v;}
function magMois(per){if(!/^\d{4}-\d{2}$/.test(per||''))return '';var mo=w.DB&&w.DB.carteRef&&w.DB.carteRef.moyenne;if(mo&&per===mo.fin){/* C192 : ventes = moyenne par mois de l'export de caisse, jamais présentées comme un seul mois */var y0=String(mo.debut).slice(0,4),y1=String(mo.fin).slice(0,4),L=String(lang()||'fr');return (y0===y1?y0:y0+'–'+y1)+' ('+(/^fr/.test(L)?'moyenne par mois':/^es/.test(L)?'media mensual':/^it/.test(L)?'media mensile':/^de/.test(L)?'Monatsdurchschnitt':/^nl/.test(L)?'maandgemiddelde':/^pt/.test(L)?'média mensal':'monthly average')+')';}var a=per.split('-');try{return new Date(+a[0],+a[1]-1,15).toLocaleDateString(lang(),{month:'long',year:'numeric'});}catch(e){return per;}}
/* V2-A5 · manque à gagner de la carte : UNE seule source pour la Carte et pour Pilotage.
   Par plat calculable et vendu : (prix HT pondéré × objectif − contribution matière) arrondi au centime × ventes de la période.
   Seuls les plats sous leur objectif comptent (un plat au-dessus ne compense pas un autre). Absent ≠ zéro : plats sans fiche
   complète ou sans ventes saisies comptés à part, jamais à 0 €. Montants en centimes entiers. */
function manqueCarte(){var r=ref(),o={version:'V2-A5',ready:!!r.ready,demo:!!r.demo,estimated:!!r.estimated,period:(r.period&&r.period!=='demo')?r.period:'',mois:'',rows:[],totalC:0,targetC:0,incompl:0,sansVol:0,actifs:0};o.mois=magMois(o.period);
 (data().plats||[]).forEach(function(p){if(!activeDish(p))return;o.actifs++;var k=w.platCalc(p);
  if(!k||!k.complete||!(k.objPond>0)||!(k.htPond>0)||!isFinite(k.contribPct))return void o.incompl++;
  if(!volumeKnown(p))return void o.sansVol++;
  var v=Number(p.vol),perC=Math.round((k.htPond*k.objPond/100-k.contribPond)*100);o.targetC+=Math.round(k.htPond*k.objPond)*v;
  if(perC>0&&v>0){var totC=Math.round(perC*v);o.rows.push({id:p.id,nom:p.nom,cat:p.cat||'',marge:k.contribPct,obj:k.objPond,perC:perC,vol:v,totC:totC,ratio:k.contribPct/k.objPond});o.totalC+=totC;}});
 o.rows.sort(function(a,b){return b.totC-a.totC||b.perC-a.perC;});o.ratio=o.targetC>0?(o.targetC-o.totalC)/o.targetC:null;return o;}
/* C208 (V39) : l'écart (pas un gain) relié au gain de la carte calculé par le moteur de Simuler (VerdictGainCarte, carte-recit-a33). */
function magGain(){try{var g=w.VerdictGainCarte&&w.VerdictGainCarte();if(!g||!g.fiable||!(g.an>0)||!(g.retenu||g.plafond))return '';return mt(g.retenu?'gain':'gainHors',{c:number(g.cap),m:money0(Math.round(g.mois)),a:money0(Math.round(g.an)),p:(g.plan>=0?'+':'−')+money0(Math.abs(Math.round(g.plan)))});}catch(e){return '';}}
function magLigne(p,a){var perC=Math.round(a.gap*100),v=Number(p.vol);if(!(perC>0))return '';var M=magMois(ref().period);
 if(ref().ready&&volumeKnown(p)&&v>0)return '<p class="cp-note cp-mag" data-mag-c="'+Math.round(perC*v)+'"><b>'+esc(mt('line',{t:money(Math.round(perC*v)/100),v:number(v),u:money(perC/100)}))+'</b>'+(M?' · '+esc(M):'')+'</p>';
 return '<p class="cp-note cp-mag">'+esc(mt('unit',{u:money(perC/100)}))+' · '+esc(mt('noVol'))+'</p>';}
function decisionPlan(P){var M=manqueCarte(),tag=M.demo?' · '+esc(mt('demo')):(M.estimated?' · '+esc(mt('estimate')):'');
 function item(x){return '<button class="cp-priority" data-cp-dish="'+esc(x.id)+'" data-cp-tone="'+tone(x.ratio)+'" data-mag-c="'+x.totC+'"><strong>'+esc(x.nom)+'</strong><span>'+esc(mt('marge',{m:pct(x.marge),o:pct(x.obj)}))+'</span><span><b>'+esc(mt('line',{t:money(x.totC/100),v:number(x.vol),u:money(x.perC/100)}))+'</b></span><b>'+esc(at('openPlan'))+'</b></button>';}
 var h='<section id="point5-menu" class="cp-card cp-advice" data-mag-total="'+M.totalC+'" data-cp-tone="'+tone(M.ratio)+'"><p class="cp-eyebrow">VERDICT · '+esc(mt('kicker'))+tag+'</p>';
 if(!M.ready)h+='<h3>'+esc(mt('kicker'))+'</h3><p class="cp-note">'+esc(mt('noRef'))+'</p>';
 else if(M.rows.length)h+='<h3 data-mag-head>'+esc(mt('head',{t:money0(M.totalC/100),m:M.mois}))+'</h3><p class="cp-note">'+esc(mt('sub',{n:number(M.rows.length),m:M.mois}))+'</p>'+(magGain()?'<p class="cp-note" data-mag-gain>'+esc(magGain())+'</p>':'')+'<p class="cp-eyebrow" style="margin-top:12px">'+esc(mt('priorities'))+'</p><div class="cp-priorities">'+M.rows.slice(0,3).map(item).join('')+'</div>'+(M.rows.length>3?'<details class="cp-method" data-mag-more><summary>'+esc(mt('more',{n:number(M.rows.length-3)}))+'</summary><div class="cp-priorities">'+M.rows.slice(3).map(item).join('')+'</div></details>':'');
 else h+='<h3 data-mag-head>'+esc(mt('headOk',{m:M.mois}))+'</h3>';
 if(M.incompl+M.sansVol)h+='<p class="cp-note" data-mag-incompl>'+esc(mt('incompl',{n:number(M.incompl+M.sansVol)}))+'</p>';
 return h+'<details class="cp-method"><summary>'+esc(mt('how'))+'</summary><p class="cp-note">'+esc(mt('def'))+'</p></details><div class="cp-actions"><button type="button" class="cp-button" data-mag-obj>'+esc(mt('btnObj'))+'</button></div><p class="cp-note">'+esc(at('guard'))+'</p></section>';
}
