var magPilSig='';
function magPilotage(){try{if(w.VIEW!=='pil')return;var fr=d.querySelector('#v-pil iframe.p41-ecran')||d.querySelector('iframe.p41-ecran');var doc=fr&&fr.contentDocument;if(!doc||!doc.body)return;
 var M=manqueCarte(),sig=[lang(),M.ready,M.demo,M.estimated,M.totalC,M.rows.length,M.incompl,M.sansVol,M.period,M.rows[0]&&M.rows[0].id,M.rows[0]&&M.rows[0].totC,magGain()].join('|'),old=doc.getElementById('modManqueCarte');if(old&&old.getAttribute('data-mag-sig')===sig)return;
 var Z={green:'vert',yellow:'jaune',orange:'orange',red:'rouge'},etat=!M.ready?'info':(Z[tone(M.ratio)]||'info'),tag=M.demo?' · '+esc(mt('demo')):(M.estimated?' · '+esc(mt('estimate')):''),x=M.rows[0];
 var h='<div class="mod-h"><p class="kicker">'+esc(mt('kicker'))+tag+'</p></div>';
 if(!M.ready)h+='<p class="sous">'+esc(mt('noRef'))+'</p>';
 else if(M.rows.length)h+='<p class="titre" data-mag-head>'+esc(mt('head',{t:money0(M.totalC/100),m:M.mois}))+'</p><p class="sous">'+esc(mt('sub',{n:number(M.rows.length),m:M.mois}))+'</p>'+(magGain()?'<p class="sous" style="margin-top:6px" data-mag-gain>'+esc(magGain())+'</p>':'')+'<p class="sous" style="margin-top:6px" data-mag-top>'+esc(mt('top',{p:x.nom,t:money(x.totC/100),v:number(x.vol),u:money(x.perC/100)}))+'</p>';
 else h+='<p class="titre" data-mag-head>'+esc(mt('headOk',{m:M.mois}))+'</p>';
 if(M.incompl+M.sansVol)h+='<p class="sous" style="margin-top:6px;font-size:13px">'+esc(mt('incompl',{n:number(M.incompl+M.sansVol)}))+'</p>';
 h+='<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:10px"><button type="button" class="btn prim" data-mag-go onclick="try{parent.verdictOuvrirManqueCarte()}catch(e){}">'+esc(mt('btn'))+'</button></div>';
 var el=old||doc.createElement('article');el.className='mod';el.id='modManqueCarte';el.setAttribute('data-etat',etat);el.setAttribute('data-mag-total',String(M.totalC));el.setAttribute('data-mag-sig',sig);el.innerHTML=h;
 if(!old){var anc=doc.getElementById('modJour');if(anc&&anc.parentNode)anc.parentNode.insertBefore(el,anc.nextSibling);else{var act=doc.getElementById('modAction');if(act&&act.parentNode)act.parentNode.insertBefore(el,act);else(doc.querySelector('main')||doc.body).appendChild(el);}}
}catch(e){}}
