/* C218 (W76) : Carte › Décisions et Ma carte suivent les prix sans rechargement. Quand une facture (ou une fiche) change
   l'écart à l'objectif ou le gain de la carte, la page ouverte est redessinée ; jamais pendant une saisie, jamais au repos. */
var magRendu='';
function magSig(){try{var M=manqueCarte();return [M.totalC,M.rows.length,M.incompl,M.sansVol,magGain()].join('|');}catch(e){return '';}}
function magSuivre(){try{
 var v=d.getElementById('v-carte');if(!magRendu||!v||!v.classList.contains('on')||guided()||['plats','menu','sales'].indexOf(S.page)<0)return;
 var a=d.activeElement;if(a&&v.contains(a)&&/^(INPUT|TEXTAREA|SELECT)$/.test(a.tagName))return;
 if(magSig()===magRendu)return;var y=w.scrollY;render(w.carteStats());w.scrollTo(0,y);}catch(e){}}
