var adviceObserver=null;
function revealAdvice(){if(adviceObserver)adviceObserver.disconnect();var cards=d.querySelectorAll('#c-'+S.page+' .cp-advice');if(!w.IntersectionObserver){cards.forEach(function(el){el.classList.add('cp-revealed');});return;}var observer=adviceObserver=new w.IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add('cp-revealed');observer.unobserve(entry.target);}});},{threshold:.12});cards.forEach(function(el){observer.observe(el);});}
function dockReturn(active){var b=d.querySelector('nav button[data-v="carte"]');if(!b)return;if(active){if(!b.hasAttribute('data-cp-back')){b._cpOriginal={html:b.innerHTML,onclick:b.getAttribute('onclick')};}b.removeAttribute('onclick');b.setAttribute('data-cp-back','');b.classList.add('cp-dock-return');b.innerHTML='<span>'+esc(t('back'))+'</span>';var parent=S.back[S.back.length-1];b.setAttribute('aria-label',t('back')+' · '+t(pages[parent?parent.page:'menu']));}else if(b._cpOriginal){b.innerHTML=b._cpOriginal.html;var label=b.querySelector('.premium-dock-label'),caption=w.t?w.t('nav.carte'):t('menu');if(label)label.textContent=caption;else{for(var i=b.childNodes.length-1;i>=0;i--)if(b.childNodes[i].nodeType===3){b.childNodes[i].nodeValue=caption;break;}}if(b._cpOriginal.onclick)b.setAttribute('onclick',b._cpOriginal.onclick);b.removeAttribute('data-cp-back');b.classList.remove('cp-dock-return');b.removeAttribute('aria-label');delete b._cpOriginal;}}

