function scoreState(){var r=ref(),sc=w.scoreCarte(w.carteStats()),ok=!!(sc.available&&Number.isFinite(sc.total)&&sc.total>=0&&sc.total<=100),sim=r.demo||data().exempleCharge,estimated=r.estimated||data().dataProvenance&&data().dataProvenance.nature==='model_estimate';return {value:ok?sc.total:null,color:ok?w.zone(sc.total).h:'#94a3b8',label:t('health'),status:sim?t('demo'):estimated?t('estimate'):'',period:r.period==='demo'?'':r.period||'',ready:ok};}

function header(){if(!isCarte())return false;var n=scoreState(),ts=d.getElementById('topScore'),box=d.getElementById('scBox'),line=d.getElementById('topZone'),sub=d.getElementById('topSub'),kp=d.getElementById('topKpi');if(!ts||!box)return false;w.SC_GENERATION=(w.SC_GENERATION||0)+1;w.SC_LAST=null;w.SC_ATTENTE=null;w.SC_TRACE_PREV=null;w.clearTimeout(w.SC_TIMER);w.clearTimeout(w.SC_TRACE_T);var trace=d.getElementById('scTrace');if(trace)trace.classList.remove('on');if(w.scClearStaleCue)w.scClearStaleCue();var value=n.ready?n.value:'—';ts.textContent=String(value);ts.title=n.label;ts.style.color=n.color;box.style.setProperty('--zc',n.color);box.classList.remove('pulse');box.setAttribute('aria-label',n.label+' · '+(n.ready?n.value+' / 100':t('incomplete'))+(n.status?' · '+n.status:''));w.scPaint(value,n.color);if(line){line.textContent=n.label+(n.status?' · '+n.status:'')+(!n.ready?' · '+t('incomplete'):'');line.style.color=n.color;}if(kp){var per=n.period,mo0=w.DB&&w.DB.carteRef&&w.DB.carteRef.moyenne;if(mo0&&per===mo0.fin)per=magMois(per);if(/^\d{4}-\d{2}$/.test(String(per||''))){try{var dp=new Date(Number(per.slice(0,4)),Number(per.slice(5,7))-1,1,12);per=dp.toLocaleDateString(lang(),{month:'long',year:'numeric'});}catch(e){}}kp.textContent=per?t('period')+' · '+per:'';}/* R240 : période lisible (« septembre 2026 »), jamais la clé brute */if(sub)sub.classList.add('on');return true;}
var toolGroups={fr:['Composer ma carte','Suivre mes coûts','Analyser et régler'],en:['Build my menu','Track my costs','Analyse and configure'],es:['Crear mi carta','Seguir costes','Analizar y ajustar'],it:['Comporre il menu','Seguire i costi','Analizzare e impostare'],de:['Karte gestalten','Kosten verfolgen','Analysieren und einstellen'],nl:['Mijn kaart samenstellen','Kosten volgen','Analyseren en instellen'],pt:['Compor o cardápio','Acompanhar custos','Analisar e configurar']};
function toolsHTML(){return '<div class="cp-more-groups">'+[['quick','rotation','ing','preps','supp'],['imports','material','factures','reconcile'],['health','sim','cstress','creg']].map(function(group,i){return '<section class="cp-more-group"><h2>'+esc(toolGroups[lang()][i])+'</h2><div class="cp-toolgrid">'+group.map(function(p){return button(t(pages[p]),p);}).join('')+'</div></section>';}).join('')+'</div>';}

var pages={menu:'menu',sales:'sales',plats:'decisions',tools:'tools',ing:'ingredients',preps:'preparations',supp:'extras',sim:'simulation',cstress:'resistance',material:'material',factures:'invoices',reconcile:'reconcile',health:'health',creg:'settings',dish:'dish',imports:'salesSource',quick:'quick',rotation:'rotate'};
function setup(){var root=d.getElementById('v-carte');if(!root)return;root.classList.toggle('cp-active',!guided());if(guided())return;
if(!d.getElementById('cp-nav')){var nav=d.createElement('div');nav.id='cp-nav';nav.className='cp-nav chips';nav.setAttribute('role','navigation');nav.setAttribute('aria-label',t('menu'));root.insertBefore(nav,root.firstChild);}
d.getElementById('cp-nav').innerHTML=['menu','sales','plats'].map(function(p){return '<button type="button" data-cp-page="'+p+'">'+esc(t(p==='tools'?'more':pages[p]))+'</button>';}).join('');
Object.keys(pages).forEach(function(p){if(!d.getElementById('c-'+p)){var el=d.createElement('div');el.className='sv';el.id='c-'+p;root.appendChild(el);}});
if(!d.getElementById('c-premium')){var prem=d.createElement('div');prem.id='c-premium';root.appendChild(prem);}
}
function render(st){magRendu=magSig();rememberGroups();setup();if(guided())return;d.getElementById('v-carte').setAttribute('data-cp-tone',tone(menuRatio()));var previousDish=S.dish;var P=w.point5Calc(st);var activeP=Object.assign({},P,{items:P.items.filter(function(x){return activeDish(x.p);})});menu();d.getElementById('c-sales').innerHTML=sales(st);d.getElementById('c-plats').innerHTML='<h2 data-cp-title tabindex="-1">'+esc(t('decisions'))+'</h2>'+context()+(P.ref.ready?'':button(t('imports'),'imports'))+decisionPlan(activeP)+decisionsList(activeP);d.getElementById('c-imports').innerHTML=title('salesSource')+w.point5ReferenceHTML(P)+w.point5ImportHTML(P);
d.getElementById('c-health').innerHTML=title('health')+w.cardScoreHeroHTML(st,w.moteur())+w.carteDixHTML();d.getElementById('c-reconcile').innerHTML=title('reconcile')+w.point7HTML();
d.getElementById('c-tools').innerHTML='';

d.getElementById('c-material').innerHTML=title('material')+w.matHTML()+w.ingSyncHTML();d.getElementById('c-factures').innerHTML=title('invoices');dish();simulator();S.dish=previousDish||S.dish;show(S.page,false);if(w.headerState)w.headerState(w.moteur());}
function section(){return S.page==='factures'?'factures':'material';}
function premium(){var holder=d.getElementById('c-premium');if(!holder)return;holder.style.display=(S.page==='material'||S.page==='factures')?'block':'none';var host=d.getElementById('c-'+S.page);if(host&&holder.parentNode!==host&&(S.page==='material'||S.page==='factures'))host.appendChild(holder);var f=holder.querySelector('iframe');if(f){try{if(f.contentWindow.VerdictCarteSection)f.contentWindow.VerdictCarteSection(section());}catch(e){}}}
function show(page,focus){if(!pages[page])return false;if(guided())return false;setup();var root=d.getElementById('v-carte');S.page=page;S.navigation++;root.setAttribute('data-cp-page',page);root.querySelectorAll(':scope > .sv').forEach(function(el){el.classList.toggle('on',el.id==='c-'+page);});var active=['menu','dish','quick','rotation'].includes(page)?'menu':['sales','imports'].includes(page)?'sales':page==='plats'?'plats':'tools';root.querySelectorAll('#cp-nav button').forEach(function(b){var on=b.dataset.cpPage===active;b.classList.toggle('on',on);b.setAttribute('aria-current',on?'page':'false');});if(page==='dish')dish();if(page==='sim')simulator();if(page==='quick')w.VerdictCarteAtelier.quick();if(page==='rotation')w.VerdictCarteAtelier.rotation();dockReturn(!['menu','sales','plats'].includes(page));premium();revealAdvice();if(focus){if(w.verdictScrollHomeTop)w.verdictScrollHomeTop();var heading=d.querySelector('#c-'+page+' [data-cp-title]');if(heading)heading.focus({preventScroll:true});}return true;}
function checkpoint(){rememberGroups();var el=d.activeElement;return {page:S.page,y:w.scrollY||d.documentElement.scrollTop||0,dish:S.dish,query:S.query,category:S.category,expanded:Object.assign({},S.expanded),focusDish:el&&el.dataset?el.dataset.cpDish:null};}
function open(page,focus,dishId){if(!pages[page]||guided())return false;if(page==='tools'){w.go('plus');return true;}if(w.VIEW==='plus'){var plus=checkpoint();plus.page='tools';w.go('carte');S.back.push(plus);if(dishId!==undefined)S.dish=dishId;return show(page,focus!==false);}if(page!==S.page){S.back.push(checkpoint());if(S.back.length>30)S.back.shift();}if(dishId!==undefined)S.dish=dishId;return show(page,focus!==false);}
function back(){var saved=w.VIEW==='plus'?S.moreOrigin:S.back.pop();if(w.VIEW==='plus')w.go('carte');if(saved&&saved.page==='tools'){S.returningMore=true;w.go('plus');S.returningMore=false;if(w.verdictCancelHomeScroll)w.verdictCancelHomeScroll();if(w.scrollTo)w.scrollTo({top:saved.y,left:0,behavior:'instant'});return;}if(!saved)return show('menu',true);if(w.verdictCancelHomeScroll)w.verdictCancelHomeScroll();S.dish=saved.dish;S.query=saved.query;S.category=saved.category;S.expanded=saved.expanded;var html=d.documentElement,anchor=html.style.overflowAnchor;html.style.overflowAnchor='none';if(saved.page==='menu')menu();show(saved.page,false);d.querySelectorAll('[data-cp-group]').forEach(function(el){el.toggleAttribute('open',!!S.expanded[el.dataset.cpGroup]);});var token=S.navigation,cancelled=false;function cancel(){cancelled=true;}['wheel','touchstart','pointerdown','keydown'].forEach(function(name){w.addEventListener(name,cancel,{passive:true,once:true});});var row=Array.from(d.querySelectorAll('#c-'+saved.page+' [data-cp-dish]')).find(function(el){return el.dataset.cpDish===saved.focusDish;});if(row)row.focus({preventScroll:true});function restore(){if(!cancelled&&token===S.navigation&&w.scrollTo)w.scrollTo({top:saved.y,left:0,behavior:'instant'});}restore();if(w.requestAnimationFrame)w.requestAnimationFrame(function(){w.requestAnimationFrame(restore);});[80,180,480].forEach(function(ms){w.setTimeout(restore,ms);});w.setTimeout(function(){html.style.overflowAnchor=anchor;['wheel','touchstart','pointerdown','keydown'].forEach(function(name){w.removeEventListener(name,cancel);});},520);}
function after(){if(guided())return;['ing','preps','supp','cstress','creg'].forEach(function(p){var el=d.getElementById('c-'+p);if(el&&!el.querySelector('.cp-pagehead'))el.insertAdjacentHTML('afterbegin',title(pages[p]));});premium();}
function preview(id){var p=dishById(id);if(!p)return false;var a=plan(p);open('sim',true,id);if(a&&a.price!=null){d.getElementById('cp-sim-price').value=a.price;var pf=d.getElementById('cp-sim-platform');if(pf)pf.value=a.pfPrice;simulate();var out=d.getElementById('cp-sim-result');out.insertAdjacentHTML('beforeend','<p class="cp-note">'+esc(at('assumptions'))+'</p>'+(a.price>Number(p.ttc)*1.1?'<p class="cp-note">'+esc(at('priceLimit'))+'</p>':''));}return true;}
w.VerdictCartePages={preview:preview,isCarte:isCarte,refreshDock:function(){var b=d.querySelector('nav button[data-v="carte"]');if(b&&b.hasAttribute('data-cp-back'))dockReturn(true);},header:header,toolsHTML:toolsHTML,scoreState:scoreState,render:render,after:after,guided:guided,open:open,section:section,scenario:scenario,plan:plan,adviceKeys:adviceKeys,adviceText:adviceText,tone:tone,menuRatio:menuRatio,text:t,keys:keys,texts:texts};
d.addEventListener('click',function(ev){var b=ev.target.closest('button[data-cp-page],[data-cp-dish],[data-cp-category],[data-cp-edit],[data-cp-add],[data-cp-back],[data-cp-expand],[data-cp-plan]');if(!b)return;if(b.hasAttribute('data-cp-page'))open(b.dataset.cpPage);else if(b.hasAttribute('data-cp-dish')){open('dish',true,b.dataset.cpDish);}else if(b.hasAttribute('data-cp-category')){S.category=b.dataset.cpCategory;menu();}else if(b.hasAttribute('data-cp-edit'))w.openPlat(b.dataset.cpEdit);else if(b.hasAttribute('data-cp-add'))open('quick');else if(b.hasAttribute('data-cp-back')){ev.preventDefault();back();}else if(b.hasAttribute('data-cp-plan')){var a=plan(dishById(S.dish));open('sim');if(a){if(b.dataset.cpPlan==='price'&&a.price!=null){d.getElementById('cp-sim-price').value=a.price;var pf=d.getElementById('cp-sim-platform');if(pf)pf.value=a.pfPrice;}if(b.dataset.cpPlan==='cost'&&a.costCap>=0)d.getElementById('cp-sim-cost').value=Math.floor((a.costCap+1e-9)*100)/100;simulate();}}else if(b.hasAttribute('data-cp-expand')){d.querySelectorAll('[data-cp-group]').forEach(function(el){el.toggleAttribute('open',b.dataset.cpExpand==='true');});rememberGroups();}});
d.addEventListener('input',function(e){if(e.target.id==='cp-search'){S.query=e.target.value;menuList();}if(['cp-sim-price','cp-sim-volume','cp-sim-cost','cp-sim-platform'].includes(e.target.id))simulate();});
d.addEventListener('change',function(e){if(e.target.id==='cp-sim-dish'){S.dish=e.target.value;simulator();}});
function start(){var sheet=w.scoreSheet;w.scoreSheet=function(){return isCarte()?w.cardScoreSheetOpen():sheet.apply(this,arguments);};var old=w.csub;w.csub=function(n,b){if(guided())return old.apply(this,arguments);return open(n);};var go=w.go;w.go=function(v){var before=w.VIEW;if(v==='plus'&&before==='carte'&&isCarte()&&!S.returningMore)S.moreOrigin=checkpoint();dockReturn(false);var result=go.apply(this,arguments);if(v==='carte'&&result!==false&&!guided()){setup();if(!d.getElementById('cp-menu-list'))w.drawCarte();if(before!=='carte'&&before!=='plus'){S.back=[];show('menu',false);}else show(S.page,false);}if(v==='plus'&&isCarte())dockReturn(true);if(w.headerState)w.headerState(w.moteur());return result;};var scroll=w.calerSur;w.calerSur=function(sel){var target=typeof sel==='string'?d.querySelector(sel):sel;if(target&&!guided()){var pane=target.closest&&target.closest('#v-carte > .sv');if(pane)show(pane.id.slice(2),false);}return scroll.apply(this,arguments);};var was=guided();if(w.MutationObserver){new MutationObserver(function(){var is=guided();if(was===is)return;was=is;var root=d.getElementById('v-carte');if(root){root.classList.toggle('cp-active',!is);if(is){root.querySelectorAll(':scope > .sv').forEach(function(el){el.classList.toggle('on',el.id==='c-plats');});}}if(w.drawCarte)w.drawCarte();}).observe(d.body,{attributes:true,attributeFilter:['class']});}if(w.VIEW==='carte')w.drawCarte();}
if(d.readyState==='loading')d.addEventListener('DOMContentLoaded',start,{once:true});else start();
